node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for any mouse-related products
const products = db.prepare(\"SELECT product_id, name FROM products WHERE LOWER(name) LIKE '%mouse%'\").all();
console.log('=== MOUSE PRODUCTS ===');
console.log(JSON.stringify(products, null, 2));

// Check if there are products with PROD- prefix anywhere
const prodPrefix = db.prepare(\"SELECT * FROM products WHERE product_id LIKE 'PROD%'\").all();
console.log('=== PROD-PREFIX PRODUCTS ===');
console.log(JSON.stringify(prodPrefix, null, 2));

// Also check rt_variants for those IDs
const v1 = db.prepare(\"SELECT * FROM rt_variants WHERE item_id LIKE '%FA0948%' OR item_id LIKE '%2DBA15%' OR item_id LIKE '%7C0240%'\").all();
console.log('=== VARIANT SEARCH ===');
console.log(JSON.stringify(v1, null, 2));

// Also list all tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('=== TABLES ===');
console.log(JSON.stringify(tables));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const ids = ['PROD-FA0948', 'PROD-2DBA15', 'PROD-7C0240'];
const products = [];

for (const id of ids) {
  const row = db.prepare('SELECT * FROM products WHERE product_id = ?').get(id);
  if (row) {
    const specs = JSON.parse(row.specs_json || '{}');
    const compatible = JSON.parse(row.compatible_with_json || '[]');
    products.push({ ...row, specs: specs, compatible_with: compatible });
  }
}

console.log(JSON.stringify(products, null, 2));
"
